#pragma once

#include <omni/otel/Attribute.h>
#include <initializer_list>
#include <utility>

namespace omni
{
namespace otel
{

template <class ValueType>
class InstrumentObserver
{
protected:
    InstrumentObserver() = default;
    ~InstrumentObserver() = default;

public:
    template <class... A>
    void observe(ValueType value, A&&... a) noexcept
    {
        this->observe(value, { Attribute(std::forward<A>(a))... });
    }

    void observe(ValueType value, std::initializer_list<Attribute> attributes) noexcept
    {
        this->observeArr(value, attributes.begin(), attributes.size());
    }

    virtual void observeArr(ValueType value, const Attribute attributes[], std::size_t attributeCount) noexcept = 0;
};

template <class ValueType>
using ObservableInstrumentCallback = void (*)(void* context, InstrumentObserver<ValueType>&);

} // namespace otel
} // namespace omni
